#!/usr/bin/env python3
"""生成 qcacld 需要的 qdf_wondertap.h（上游 OPAirDrop 漏提交这个文件）。

qdf_wondertap_*_t 只是 wonder 公共头 wondertap.h 里类型的别名，
所以直接内联 wondertap.h 再加 typedef 即可。
用法: make_qdf_wondertap.py <tree_root>
"""
import sys
from pathlib import Path

TYPEDEFS = """
/* ---- auto-generated aliases for qcacld ---- */
typedef enum wondertap_rate_preamble qdf_wondertap_rate_preamble_t;
typedef enum wondertap_rate_bw qdf_wondertap_rate_bw_t;
typedef enum wondertap_rate_gi qdf_wondertap_rate_gi_t;
typedef enum wondertap_filter_type qdf_wondertap_filter_type_t;
typedef enum wondertap_tx_rate_mask_enable qdf_wondertap_tx_rate_mask_enable_t;
typedef struct wondertap_set_freq_params qdf_wondertap_set_freq_params_t;
typedef struct wondertap_bssid_filter_params qdf_wondertap_bssid_filter_params_t;
typedef struct wondertap_frame_filter_params qdf_wondertap_frame_filter_params_t;
typedef struct wondertap_fixed_tx_rate_params qdf_wondertap_tx_rate_params_t;
typedef struct wondertap_tx_rate_mask_params qdf_wondertap_tx_rate_mask_params_t;
typedef struct wondertap_capability qdf_wondertap_capability_t;
typedef struct wondertap_init_params qdf_wondertap_init_params_t;
typedef struct wondertap_deinit_params qdf_wondertap_deinit_params_t;
typedef struct wondertap_priv qdf_wondertap_priv_t;
typedef struct wondertap_ops qdf_wondertap_ops_t;
typedef struct wonder_txd qdf_wonder_txd_t;
"""


def main():
    root = Path(sys.argv[1])
    src = root / 'vendor/oplus/kernel/wifi/wonder/include/wonder/wondertap.h'
    dst = root / 'vendor/qcom/opensource/wlan/qca-wifi-host-cmn/qdf/inc/qdf_wondertap.h'
    if not src.exists():
        print('MISSING wondertap.h:', src)
        return 1
    body = src.read_text()
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_text('/* auto-generated by make_qdf_wondertap.py */\n'
                   + body + '\n' + TYPEDEFS)
    print('written', dst, dst.stat().st_size, 'bytes')
    return 0


if __name__ == '__main__':
    sys.exit(main())
